    arChallenge:
      "شركة تركيب معدات إطفاء الحريق تحتاج إلى موافقة الدفاع المدني بدبي (DCD) على وحدة مكتبية في مبنى Burlington Tower 3 في دبي، وفق عرض السعر LML/QTN/1104. تُعدّ موافقة DCD بمثابة الاعتماد المطلوب للسلامة من الحرائق وسلامة الأرواح في مشاريع تشطيب المكاتب داخل المباني التجارية، لذا يجب أن تتوافق مخططات المكتب مع اشتراطات الدفاع المدني قبل الحصول على موافقة التصميم والتفتيش النهائي. تغطي الرسوم المهنية البالغة 3,200 درهم إماراتي إعداد المخططات وفق اشتراطات الدفاع المدني، والحصول على موافقة التصميم من DCD، وإجراء التفتيش الذي يُطلق شهادة إتمام الأعمال.\n\nويُبقي عرض السعر الرسوم نهائية مع حدود واضحة: يوفّر العميل جميع المخططات والمستندات والملفات الخضراء القائمة الأخرى؛ وتُحمَّل رسوم إضافية على أي متطلبات موافقة استثنائية أو فشل في التفتيش أو مراجعة للتصميم؛ وتُحتسب ضريبة القيمة المضافة بشكل منفصل. إن تأكيد المستندات القائمة منذ البداية هو ما يحمي الرسوم المعروضة البالغة 3,200 درهم إماراتي.",
