    arChallenge:
      "الخليج التجاري مجتمع رئيسي تديره هيئة دبي التنموية (DDA) ويضم أبراجاً شاهقة في وسط دبي، ويغطي هذا العرض مسار موافقة DDA و DCD الذي يحتاجه العقار هناك قبل اعتماد أعمال التشطيبات. يجمع موضوع الموافقة بين هيئة دبي التنموية (DDA) التي تنظّم موافقة التصميم داخل المجتمع، والدفاع المدني بدبي (DCD) الذي يراجع جوانب السلامة من الحرائق وسلامة الأرواح في التصميم، لذا يجب أن تلتزم مجموعة المخططات نفسها باشتراطات الجهتين معاً، وأن يعقبها تفتيش يُصدر بعده شهادة الإتمام.\nوتُعرَّف الرسوم البالغة 7,000 درهم إماراتي حول المدخلات التي يتحكم بها العميل. إذ يوفّر العميل المخططات والمستندات والملفات الخضراء القائمة؛ وكل متطلب موافقة استثنائي أو فشل في التفتيش أو مراجعة للتصميم يحمل رسماً إضافياً؛ وتُحتسب ضريبة القيمة المضافة بشكل منفصل. ويشير عرض السعر أيضاً إلى أن السعر قد يختلف إذا طُلبت شهادة عدم ممانعة (NOC) من إدارة مبنى البرج، لذا فإن تأكيد موقف إدارة المبنى مبكراً هو ما يبقي السعر المعروض البالغ 7,000 درهم إماراتي واقعياً. ولا يلتزم عرض السعر بجدول زمني ثابت للإتمام.",
